const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
const src = m[1];
// stubs
const calls = [];
const ctxStub = new Proxy({}, { get(t, k){ if(k==='createRadialGradient') return () => ({addColorStop(){}}); return (...a)=>{}; }, set(){return true;} });
const document = { getElementById: () => ({ getContext: () => ctxStub, width:800, height:800 }) };
const requestAnimationFrame = () => 0;
const window = {};
const fn = new Function('window','document','requestAnimationFrame', src + '; return window.__bench;');
const bench = fn(window, document, requestAnimationFrame);
// run 10 seconds
for (let i=0;i<100;i++) bench.step(0.1);
const s = bench.getState();
console.log('t', s.t, 'angle', s.poly.angle);
console.log('balls', s.balls.length);
// verify containment: inside polygon
function inside(b){
  const n=9,R=260,CX=400,CY=400,a0=-Math.PI/2+s.poly.angle;
  let insideAll=true;
  for(let i=0;i<n;i++){
    const A={x:CX+Math.cos(a0+i*2*Math.PI/n)*R,y:CY+Math.sin(a0+i*2*Math.PI/n)*R};
    const B={x:CX+Math.cos(a0+(i+1)*2*Math.PI/n)*R,y:CY+Math.sin(a0+(i+1)*2*Math.PI/n)*R};
    // cross product sign: for CCW polygon interior on left; our order with y down... just check distance to each edge line <=0 relative to center
    const ex=B.x-A.x, ey=B.y-A.y;
    const v = (b.x-A.x)*ey - (b.y-A.y)*ex;
    const cv = (CX-A.x)*ey - (CY-A.y)*ex;
    if (Math.sign(v)!==Math.sign(cv)) insideAll=false;
  }
  return insideAll;
}
let ok = s.balls.every(b=>inside(b));
console.log('all inside polygon:', ok);
// overlaps
let overlap=false;
for(let i=0;i<s.balls.length;i++)for(let j=i+1;j<s.balls.length;j++){
  const d=Math.hypot(s.balls[i].x-s.balls[j].x, s.balls[i].y-s.balls[j].y);
  if(d<28-1e-6) overlap=true;
}
console.log('no overlap:', !overlap);
console.log('finite:', s.balls.every(b=>[b.x,b.y,b.vx,b.vy].every(Number.isFinite)));
console.log(JSON.stringify(s.balls[0]));
"

